 public static void Run(){try{
 var managed=A("-gameManaged");if(LoadLibrary(Path.GetFullPath(Path.Combine(managed,"../Plugins/x86_64/PipelinePlugin.dll")))==IntPtr.Zero)throw new Exception("Native PipelinePlugin load failed");AppDomain.CurrentDomain.AssemblyResolve+=(_,e)=>{var p=Path.Combine(managed,new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};
 var asm=Assembly.LoadFrom(A("-modAssembly"));Type T(string n)=>asm.GetType("BridgeBuilder.Bridges."+n,true);var st=T("MovableStructureTiles").GetMethod("NativeSurface",F).ReturnType;var surface=FormatterServices.GetUninitializedObject(st);using(var br=new BinaryReader(File.OpenRead(A("-finishedSurface"))))st.GetMethod("ReadHeader",F).Invoke(surface,new object[]{br});
 var root=A("-inputs");File.WriteAllText(Path.Combine(root,"retile-slots.tsv"),"");using(var w=new StreamWriter(Path.Combine(root,"actual-plan-disposition.csv"))){w.WriteLine("lod,delta,face,removed,fragmentTriangles,coverage");for(int lod=0;lod<3;lod++){Vector3[] p;int[] ix;using(var r=new BinaryReader(File.OpenRead(Path.Combine(root,"lod"+lod+".bin")))){p=new Vector3[r.ReadInt32()];ix=new int[r.ReadInt32()];for(int i=0;i<p.Length;i++)p[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());for(int i=0;i<ix.Length;i++)ix[i]=r.ReadInt32();}
 foreach(float delta in new[]{0f,3f,12f}){var plan=T("Lift05StructurePlan").GetMethod("Create",F).Invoke(null,new object[]{lod,p,ix,delta,surface,new Vector2(0,.25f),new Vector2(1,.75f)});Lift05FullNativeCheck.Check(asm,root,lod,plan,delta);if(lod<2){using(var gr=new BinaryReader(File.OpenRead(Path.Combine(root,"glass/lod"+lod+".bin")))){int gv=gr.ReadInt32(),gi=gr.ReadInt32(),ga=gr.ReadInt32();var gix=new int[gi];for(int g=0;g<gi;g++)gix[g]=gr.ReadInt32();Vector3[] gp=new Vector3[gv];for(int g=0;g<ga;g++){int at=gr.ReadInt32(),fmt=gr.ReadInt32(),dim=gr.ReadInt32(),len=gr.ReadInt32();var bytes=gr.ReadBytes(len);if(at==0)for(int v=0;v<gv;v++)gp[v]=new Vector3(BitConverter.ToSingle(bytes,v*12),BitConverter.ToSingle(bytes,v*12+4),BitConverter.ToSingle(bytes,v*12+8));}var glassPlan=T("Lift05Glass").GetMethod("Create",F).Invoke(null,new object[]{lod,gp,gix,delta});Lift05FullNativeCheck.Check(asm,root,lod,glassPlan,delta,1);}}var mask=((bool[][])G(plan,"RemoveTriangles"))[0];var fragments=((IEnumerable)G(plan,"Fragments")).Cast<object>().ToDictionary(x=>(int)G(x,"Triangle"));
 for(int face=0;face<mask.Length;face++){double coverage=mask[face]?0:1;int triangles=0;if(fragments.TryGetValue(face,out var fr)){var ids=(int[])G(fr,"Indices");triangles=ids.Length/3;coverage=0;double[] B(int id){var b=new double[3];if(id<p.Length){b[Array.IndexOf(ix,id,face*3,3)-face*3]=1;return b;}var construction=plan.GetType().GetMethod("Construction",F).Invoke(plan,new object[]{id-p.Length});int[] vs={(int)G(construction,"A"),(int)G(construction,"B"),(int)G(construction,"C")};double wb=Convert.ToDouble(G(construction,"WeightB")),wc=Convert.ToDouble(G(construction,"WeightC"));double[] ws={1-wb-wc,wb,wc};for(int j=0;j<3;j++)if(ws[j]!=0)b[Array.IndexOf(ix,vs[j],face*3,3)-face*3]+=ws[j];return b;}
 for(int k=0;k<ids.Length;k+=3){var a=B(ids[k]);var b=B(ids[k+1]);var c=B(ids[k+2]);coverage+=(b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1]);}}
 w.WriteLine($"{lod},{delta},{face},{mask[face]},{triangles},{coverage:R}");}Debug.Log($"PASS Lift05 actual disposition lod={lod} delta={delta} faces={mask.Length} fragments={fragments.Count}");}}}
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
